namespace MapEdit.glows;

public class GlowList
{
	private Glow[] glow;

	public int totalGlows;

	public int idx;

	public GlowList(int idx)
	{
		this.idx = idx;
		glow = new Glow[128];
		for (int i = 0; i < glow.Length; i++)
		{
			glow[i] = new Glow();
		}
	}

	public void AddGlow(Vector2 loc, float r, float g, float b, float size, int type)
	{
		_ = (int)loc.X;
		_ = 7;
		float num = size * 64f;
		float num2 = 200f;
		if (!(loc.X + num < 0f) && !(loc.Y + num < 0f) && !(loc.X - num > ScrollManager.screenSize.X) && !(loc.Y - num > ScrollManager.screenSize.Y))
		{
			float num3 = 1f;
			if (loc.X < 0f - num2)
			{
				num3 *= 1f - (0f - loc.X - num2) / num;
			}
			if (loc.Y < 0f - num2)
			{
				num3 *= 1f - (0f - loc.Y - num2) / num;
			}
			if (loc.X > ScrollManager.screenSize.X + num2)
			{
				num3 *= 1f - (loc.X - (ScrollManager.screenSize.X + num2)) / num;
			}
			if (loc.Y > ScrollManager.screenSize.Y + num2)
			{
				num3 *= 1f - (loc.Y - (ScrollManager.screenSize.Y + num2)) / num;
			}
			if (totalGlows < glow.Length)
			{
				glow[totalGlows].Init(loc, r, g, b, size * num3, type);
				totalGlows++;
			}
		}
	}

	public void Draw(XTexture xt)
	{
		for (int i = 0; i < totalGlows; i++)
		{
			glow[i].Draw(xt, idx);
		}
	}

	internal void Clear()
	{
		totalGlows = 0;
	}

	internal void DrawForLightMode(XTexture xt)
	{
		for (int i = 0; i < totalGlows; i++)
		{
			glow[i].DrawForLightMode(xt, idx);
		}
	}
}
using Microsoft.Xna.Framework;
