namespace MapEdit.glows;

public class GlowMgr
{
	public const int GLOW_LIGHTMAP = 0;

	public const int GLOW_NORMAL = 1;

	public float alpha;

	public GlowList[] list = new GlowList[2]
	{
		new GlowList(0),
		new GlowList(1)
	};

	public Effect lightEffect;

	public Texture2D cloudsTex;

	public const int TOTAL_ADDS = 3;

	public float greenLanternFrame;

	public float greenLanternAlpha;

	private Vector2[] addVec;

	public float lightFac = 1f;

	public GlowMgr(ContentManager Content)
	{
		lightEffect = Content.Load<Effect>("fx/lightmap");
		cloudsTex = Content.Load<Texture2D>("gfx/waterstain");
		addVec = new Vector2[3];
	}

	public void Draw(XTexture xt)
	{
		list[1].Draw(xt);
	}

	internal void Add(int type, Vector2 loc, float r, float g, float b, float size, int glowType)
	{
		list[type].AddGlow(loc, r, g, b, size, glowType);
	}

	internal void Draw(XTexture xt, int idx)
	{
		list[idx].Draw(xt);
	}

	internal void Clear()
	{
		list[1].Clear();
	}

	internal void Prepare(XTexture xt, RenderTarget2D lightTarg)
	{
		GraphicsDevice graphicsDevice = lightTarg.GraphicsDevice;
		graphicsDevice.SetRenderTarget(lightTarg);
		graphicsDevice.Clear(new Color(1f, 1f, 1f, 1f));
		SpriteTools.BeginSubtractive();
		list[0].DrawForLightMode(xt);
		SpriteTools.End();
		list[0].Clear();
	}

	internal void Update()
	{
		if (greenLanternFrame > 0f)
		{
			greenLanternFrame -= Game1.frameTime;
			if (greenLanternAlpha < 1f)
			{
				greenLanternAlpha += Game1.frameTime;
				if (greenLanternAlpha > 1f)
				{
					greenLanternAlpha = 1f;
				}
			}
		}
		else if (greenLanternAlpha > 0f)
		{
			greenLanternAlpha -= Game1.frameTime;
			if (greenLanternAlpha < 0f)
			{
				greenLanternAlpha = 0f;
			}
		}
		addVec[0].X += Game1.frameTime * 6f;
		addVec[0].Y += Game1.frameTime * 4f;
		addVec[1].X += Game1.frameTime * -3.5f;
		addVec[1].Y += Game1.frameTime * -7f;
		addVec[2].X += Game1.frameTime * -6f;
		addVec[2].Y += Game1.frameTime * -2.5f;
		float num = 512f;
		for (int i = 0; i < addVec.Length; i++)
		{
			if (addVec[i].X >= num)
			{
				addVec[i].X -= num;
			}
			if (addVec[i].X < 0f)
			{
				addVec[i].X += num;
			}
			if (addVec[i].Y >= num)
			{
				addVec[i].Y -= num;
			}
			if (addVec[i].Y < 0f)
			{
				addVec[i].Y += num;
			}
		}
	}

	internal void Draw(RenderTarget2D lightTarg)
	{
		lightEffect.Parameters["alpha"].SetValue(alpha);
		_ = ScrollManager.scroll;
		Vector2 realLoc = ScrollManager.GetRealLoc(new Vector2(0f, 0f), 2f);
		Vector2 realLoc2 = ScrollManager.GetRealLoc(ScrollManager.screenSize, 2f);
		Vector2 realLoc3 = ScrollManager.GetRealLoc(new Vector2(0f, 0f), 6f);
		ScrollManager.GetRealLoc(ScrollManager.screenSize, 6f);
		Vector2 realLoc4 = ScrollManager.GetRealLoc(new Vector2(0f, 0f), 7f);
		ScrollManager.GetRealLoc(ScrollManager.screenSize, 7f);
		lightEffect.Parameters["scroll"].SetValue(realLoc + addVec[0]);
		lightEffect.Parameters["scroll2"].SetValue(realLoc3 + addVec[1]);
		lightEffect.Parameters["scroll3"].SetValue(realLoc4 + addVec[2]);
		lightEffect.Parameters["scrollDif"].SetValue(realLoc2 - realLoc);
		lightEffect.Parameters["lightFac"].SetValue(lightFac);
		SpriteTools.sprite.GraphicsDevice.Textures[1] = cloudsTex;
		lightEffect.Parameters["CloudsTexture"].SetValue(cloudsTex);
		lightEffect.Parameters["LightTexture"].SetValue(lightTarg);
		SpriteTools.BeginSubtractive(lightEffect);
		SpriteTools.sprite.Draw(lightTarg, new Rectangle(0, 0, (int)ScrollManager.screenSize.X, (int)ScrollManager.screenSize.Y), new Color(1f, 1f, 1f, alpha));
		SpriteTools.End();
		SpriteTools.sprite.GraphicsDevice.Textures[1] = null;
	}
}

using System.IO;

namespace ProjectTower.player;

public class PlayerBeast
{
	public int kills;

	public int killedBy;

	public int[] drops;

	public PlayerBeast()
	{
		kills = 0;
		killedBy = 0;
		drops = new int[6];
	}

	public PlayerBeast(BinaryReader reader)
	{
		kills = reader.ReadInt32();
		killedBy = reader.ReadInt32();
		drops = new int[6];
		for (int i = 0; i < drops.Length; i++)
		{
			drops[i] = reader.ReadInt32();
		}
	}

	public PlayerBeast(PlayerBeast playerBeast)
	{
		kills = playerBeast.kills;
		killedBy = playerBeast.killedBy;
		drops = new int[6];
		for (int i = 0; i < drops.Length; i++)
		{
			drops[i] = playerBeast.drops[i];
		}
	}

	internal void Write(BinaryWriter writer)
	{
		writer.Write(kills);
		writer.Write(killedBy);
		for (int i = 0; i < drops.Length; i++)
		{
			writer.Write(drops[i]);
		}
	}
}
using System.Collections.Generic;
using System.IO;
using MonsterEdit.monsters;
using ProjectTower.character;

namespace ProjectTower.player;

public class PlayerBeasts
{
	private Player player;

	public Dictionary<string, PlayerBeast> playerBeast;

	public PlayerBeasts(Player player)
	{
		this.player = player;
		playerBeast = new Dictionary<string, PlayerBeast>();
	}

	public void Write(BinaryWriter writer)
	{
		writer.Write(playerBeast.Count);
		foreach (KeyValuePair<string, PlayerBeast> item in playerBeast)
		{
			writer.Write(item.Key);
			item.Value.Write(writer);
		}
	}

	public void Read(BinaryReader reader)
	{
		playerBeast = new Dictionary<string, PlayerBeast>();
		int num = reader.ReadInt32();
		for (int i = 0; i < num; i++)
		{
			string key = reader.ReadString();
			PlayerBeast value = new PlayerBeast(reader);
			playerBeast.Add(key, value);
		}
	}

	internal void AddKill(MonsterDef monsterDef)
	{
		AddKill(monsterDef.name);
		string name = monsterDef.name;
		if (!(name == "ruinghost"))
		{
			if (name == "ruinknight")
			{
				AddKill("ruinghost");
			}
		}
		else
		{
			AddKill("ruinknight");
		}
	}

	private void AddKill(string name)
	{
		if (!playerBeast.ContainsKey(name))
		{
			playerBeast.Add(name, new PlayerBeast());
		}
		playerBeast[name].kills++;
	}

	internal void AddDrop(MonsterDef monsterDef, int drop)
	{
		if (!playerBeast.ContainsKey(monsterDef.name))
		{
			playerBeast.Add(monsterDef.name, new PlayerBeast());
		}
		playerBeast[monsterDef.name].drops[drop]++;
	}

	internal bool HasBeast(MonsterDef mDef)
	{
		return playerBeast.ContainsKey(mDef.name);
	}

	internal void CopyFrom(PlayerBeasts copyBeasts)
	{
		playerBeast = new Dictionary<string, PlayerBeast>();
		foreach (KeyValuePair<string, PlayerBeast> item in copyBeasts.playerBeast)
		{
			playerBeast.Add(item.Key, new PlayerBeast(item.Value));
		}
	}

	internal bool HasBeastDrop(MonsterDef mDef, int i)
	{
		if (playerBeast.ContainsKey(mDef.name) && playerBeast[mDef.name].drops[i] > 0)
		{
			return true;
		}
		return false;
	}

	internal void AddKilledBy(Character character)
	{
		MonsterDef monsterDef = MonsterCatalog.catalog[character.monsterIdx];
		if (!playerBeast.ContainsKey(monsterDef.name))
		{
			playerBeast.Add(monsterDef.name, new PlayerBeast());
		}
		playerBeast[monsterDef.name].killedBy++;
	}

	internal void AddKilledBy(string name)
	{
		if (!playerBeast.ContainsKey(name))
		{
			playerBeast.Add(name, new PlayerBeast());
		}
		playerBeast[name].killedBy++;
	}

	internal void Reset()
	{
		playerBeast = new Dictionary<string, PlayerBeast>();
	}
}
